yakit.AutoInitYakit()

# Input your code!

#爬
def bing(q, max_page) {
    q = codec.EscapeUrl(q)
    newCookie = ""
    referer=""
    start_page = 0
    again = 5
    result = []
    for start_page < max_page{
        text = f`GET /search?q=${q}&first=${start_page*10} HTTP/1.1
Host: cn.bing.com
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:123.0) Gecko/20100101 Firefox/123.0
Accept-Encoding: gzip, deflate
Accept: */*
Connection: keep-alive
`
        try {
            rsp, req = poc.HTTPEx(text, poc.timeout(8), poc.replaceHeader("Cookie", newCookie), poc.replaceHeader("referer", referer))~
            newCookie = string(rsp.GetHeadersFull()["Set-Cookie"]).Trim("[", "]")
            referer=rsp.Url

            html = string(rsp.GetBody())
            doc = xpath.LoadHTMLDocument(html)~
            nodes := xpath.Find(doc, "//ol/li[@class='b_algo']")
            if !nodes {
                yakit.Info(f"${req.URL.String()}\n没有找到链接,重试一次")
                sleep(1)
                if again > 0 {
                    again -= 1
                    continue
                } else {
                    break
                }
            }
            

            for _, node := range nodes {
                node_1 = xpath.FindOne(node, `//h2/a`)
                title = xpath.InnerText(node_1)
                url = xpath.SelectAttr(node_1, 'href')
                url = codec.DecodeUrl(url)~
                url = codec.DecodeUrl(url)~
                host, port = str.ParseStringToHostPort(url)~
                host = f`${host}:${port}`

                node_2 = xpath.FindOne(node, `//div/p`)
                describe = xpath.InnerText(node_2)
                describe = codec.FixUTF8(describe)

                link = {"title": title, "url": url, "desc": describe, "page": start_page, "host": host}
                result.Append(link)
            }
            

            start_page += 1
        } catch err {
            yakit.Info(f"max_page=${max_page}出了点问题\n${err}")
            if again > 0 {
                again -= 1
            } else {
                break
            }
        }
    }
    

    return result
}

def ResultOut(Table_name, data) {
    yakit.EnableTable(Table_name, ["title", "url", "desc", "host"])
    for i in data {
        yakit.Output(yakit.TableData(Table_name, i))
    }
}

def generate_html(q, data, output_filename) {
    html_content = f`<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>必应搜索</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            box-shadow: 0 2px 3px rgba(0, 0, 0, 0.1);
        }
        th, td {
            border: 1px solid #ddd;
            padding: 12px;
            text-align: left;
            vertical-align: top;
        }
        th {
            background-color: #f8f8f8;
            color: #333;
        }
        .expandable {
            cursor: pointer;
            color: #007BFF;
            text-decoration: underline;
        }
        .desc-row {
            display: none;
            background-color: #f9f9f9;
        }
        .desc {
            padding-left: 20px;
            color: #555;
            max-width: calc(100% - 40px); /* 40px 是 padding-left 的两倍 */
            white-space: pre-wrap; /* 保留空白符并自动换行 */
        }
        .url-cell {
            max-width: 200px; /* 减少URL字段的最大宽度 */
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .url-cell a {
            color: #007BFF;
            text-decoration: none;
        }
        .url-cell a:hover {
            text-decoration: underline;
        }
        .host-cell {
            max-width: 100px; /* 减少Host字段的最大宽度 */
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .detail-cell {
            width: 150px; /* 增加详情字段的宽度 */
        }
    </style>
</head>
<body>

<h2>${q}</h2>

<table>
    <thead>
        <tr>
            <th>Title</th>
            <th>URL</th>
            <th>Host</th>
            <th>详情</th>
        </tr>
    </thead>
    <tbody>`

    # 添加数据行到表格中
    for item in data {
        html_content += f`
        <tr>
            <td>${item['title']}</td>
            <td><a href="${item['url']}" target="_blank">${item['url']}</a></td>
            <td>${item['host']}</td>
            <td><span class="expandable" onclick="toggleDesc(this)">展开</span></td>
        </tr>
        <tr class="desc-row">
            <td colspan="4" class="desc">${item['desc']}</td>
        </tr>
        `
    }
    

    html_content += `
     </tbody>
</table>

<script>
    function toggleDesc(element) {
        const row = element.closest('tr');
        const descRow = row.nextElementSibling;
        if (descRow.classList.contains('desc-row')) {
            if (descRow.style.display === 'none' || descRow.style.display === '') {
                descRow.style.display = 'table-row';
            } else {
                descRow.style.display = 'none';
            }
        }
    }
</script>

</body>
</html>
    `
    html_path = f`${yakit.GetHomeTempDir()}\\${output_filename}.html`
    f = file.Open(html_path)~
    defer f.Close()
    f.Write(html_content)
    yakit.File(html_path, "已生成html")
}

#q:搜索词 maxpage:爬取最大页数 opname:生成html的文件名\表名 is_html:是否生成html
def crawlone(q, maxpage, opname, is_html) {
    r = bing(q, maxpage)
    ResultOut(opname, r)
    if is_html {
        generate_html(q, r, opname)
    }
}

q = cli.String("q", cli.setRequired(true), cli.setVerboseName("搜索词"), cli.setHelp("想搜点什么？"))
html = cli.Bool("html", cli.setVerboseName("生成html"), cli.setHelp("在yakit临时目录下生成html文件"))
mp = cli.Int("maxpage", cli.setRequired(true), cli.setVerboseName("最大爬取页数"), cli.setHelp("一页大概10条url"), cli.setDefault(5))
cli.check()

def() {
    yakit.Info(f`搜索词:${q}`)
    i = 1
    opname = f"${i}_" + str.RandStr(5)
    crawlone(q, mp, opname, html)
    yakit.Info("程序结束")
}()
